INSERT INTO products ("id", "batch_id", "farmer_id", "category_id", "name", "name_ms", "slug", "description", "description_ms", "harvest_date", "expiry_date", "quantity_available", "minimum_order", "unit", "price_per_unit", "middleman_price", "storage_temp", "farm_location", "grade", "pesticide_status", "image_path", "is_spotlight", "spotlight_headline", "spotlight_subtitle", "tag", "approval_status", "created_at") VALUES (5, 'AF-FMX-2026-BOX1', 1, 6, 'Famox Weekly Harvest Box (6kg Bundle)', 'Kotak Segar Mingguan Famox (6kg)', 'famox-weekly-harvest-box', 'Curated weekly fresh box containing 1kg Roma Tomatoes, 1kg Butterhead Lettuce, 1kg Japanese Cucumbers, 1kg Sawi, 1kg Sweet Corn, and 1kg Long Beans. Perfect for a family of 4.', 'Kotak sayur segar mingguan lengkap: 1kg Tomato Roma, 1kg Salad Butterhead, 1kg Timun Jepun, 1kg Sawi Hijau, 1kg Jagung Manis, dan 1kg Kacang Panjang. Jimat untuk keluarga 4 orang.', '2026-09-02 05:00 AM', '2026-09-12', 75.00, 1.00, 'box (6kg assorted)', 28.00, 42.00, 'Keep Chilled', 'Famox Central Hub, Lunas Kedah', 'Multi-Farm Grade A Curated', 'All Farm Batches MyGAP Certified', 'https://images.unsplash.com/photo-1610348725531-843dff563e2c?w=800&auto=format&fit=crop&q=80', 1, 'A week of vibrant health in one box.', 'Assorted greens, vine tomatoes, sweet corn, and crisp cucumbers.', 'BEST VALUE BUNDLE', 'approved', '2026-09-02 20:37:05');
